const f = $input.first().json;
const MAX = 6; // número de linhas da tabela no modelo do Docs

// ---------- Utilitários ----------

// Normaliza nomes: "Serviços: " -> "servicos"
const norm = (s) => String(s)
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]/g, '');

// Busca um campo aceitando variações de nome
const campo = (...nomes) => {
  const alvos = nomes.map(norm);
  for (const [k, v] of Object.entries(f)) {
    if (alvos.includes(norm(k))) return v;
  }
  return '';
};

// Converte para número: 2500, "2500", "2.500,00", "2500.50", "x3"
const num = (s) => {
  if (typeof s === 'number') return s;
  s = String(s ?? '').trim();
  if (!s) return 0;
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  s = s.replace(/[^0-9.\-]/g, '');
  return parseFloat(s) || 0;
};

// Formata em reais: 2500 -> "2.500,00"
const brl = (v) => v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// Formata CPF ou CNPJ (recupera zeros à esquerda perdidos)
const formatarDoc = (v) => {
  let d = String(v ?? '').replace(/\D/g, '');
  if (!d) return '';
  if (d.length <= 11) {
    d = d.padStart(11, '0');
    return d.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
  }
  d = d.padStart(14, '0');
  return d.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, '$1.$2.$3/$4-$5');
};

// Formata telefone: 81986831317 -> (81) 98683-1317
const formatarTel = (v) => {
  let d = String(v ?? '').replace(/\D/g, '');
  if (d.length > 11 && d.startsWith('55')) d = d.slice(2); // remove +55
  if (d.length === 11) return d.replace(/(\d{2})(\d{5})(\d{4})/, '($1) $2-$3');
  if (d.length === 10) return d.replace(/(\d{2})(\d{4})(\d{4})/, '($1) $2-$3');
  return d;
};

// ---------- Leitura dos campos ----------

const nome     = String(campo('Nome', 'Nome do cliente')).trim();
const email    = String(campo('E-mail', 'Email')).trim();
const docTxt   = formatarDoc(campo('CPF/CNPJ', 'CPF', 'CNPJ'));
const telefone = formatarTel(campo('Telefone', 'Celular', 'WhatsApp'));
const textoItens = campo('Serviços', 'Servicos', 'Itens');
const desconto   = num(campo('Desconto', 'Desconto à vista (R$)'));
const nParcelas  = Math.round(num(campo('Parcelas'))) || 3;
const prazo      = String(campo('Prazo', 'Prazo (dias úteis)') ?? '').trim();
const endereco = String(campo('Endereço', 'Endereco') ?? '').trim();

// ---------- Itens (uma linha = um item) ----------

const linhas = String(textoItens || '')
  .split(/\r?\n/)              // aceita \r\n e \n
  .map(l => l.trim())
  .filter(Boolean);

if (linhas.length === 0) throw new Error('Nenhum serviço informado.');
if (linhas.length > MAX) throw new Error(`Máximo de ${MAX} serviços por orçamento (recebidos: ${linhas.length}).`);

const itens = linhas.map((l, i) => {
  const partes = l.split('|').map(p => p.trim());
  if (partes.length !== 3) {
    throw new Error(`Linha ${i + 1} fora do formato "Descrição | Qtd | Valor": ${l}`);
  }
  const [desc, qtd, unit] = partes;
  const q = num(qtd) || 1;
  const u = num(unit);
  return { desc, q, u, total: q * u };
});

// ---------- Cálculos ----------

const subtotal     = itens.reduce((s, it) => s + it.total, 0);
const totalFinal   = subtotal - desconto;
const entrada = num(campo('Entrada', 'Entrada (R$)'));

if (entrada < 0) throw new Error('A entrada não pode ser negativa.');
if (entrada > subtotal) {
  throw new Error(`A entrada (R$ ${brl(entrada)}) é maior que o subtotal (R$ ${brl(subtotal)}).`);
}

const valorParcela = (subtotal - entrada) / nParcelas;

const hoje = $now.setZone('America/Recife');
const numero = 'ORC-' + hoje.toFormat('yyyyMMdd-HHmm');

// ---------- Marcadores -> valores ----------

const r = {
  '{{NUMERO}}':        numero,
  '{{DATA}}':          hoje.toFormat('dd/MM/yyyy'),
  '{{VALIDADE}}':      hoje.plus({ days: 15 }).toFormat('dd/MM/yyyy'),
  '{{NOME}}':          nome,
  '{{EMAIL}}':         email,
  '{{DOCUMENTO}}':     docTxt,
  '{{TELEFONE}}':      telefone,
  '{{ENDERECO}}':      endereco,
  '{{SUBTOTAL}}':      'R$ ' + brl(subtotal),
  '{{DESCONTO}}':      desconto > 0 ? '- R$ ' + brl(desconto) : 'R$ 0,00',
  '{{TOTAL_FINAL}}':   'R$ ' + brl(totalFinal),
  '{{ENTRADA}}':       'R$ ' + brl(entrada),
  '{{NUM_PARCELAS}}':  String(nParcelas),
  '{{VALOR_PARCELA}}': 'R$ ' + brl(valorParcela),
  '{{PRAZO}}':         prazo,
};

for (let i = 1; i <= MAX; i++) {
  const it = itens[i - 1];
  r[`{{I${i}_NUM}}`]   = it ? String(i).padStart(2, '0') : '';
  r[`{{I${i}_DESC}}`]  = it ? it.desc : '';
  r[`{{I${i}_QTD}}`]   = it ? String(it.q) : '';
  r[`{{I${i}_UNIT}}`]  = it ? brl(it.u) : '';
  r[`{{I${i}_TOTAL}}`] = it ? brl(it.total) : '';
}

// Formato da API do Google Docs
const requests = Object.entries(r).map(([marcador, valor]) => ({
  replaceAllText: {
    containsText: { text: marcador, matchCase: true },
    replaceText: valor,
  },
}));

return [{
  json: {
    numero,
    nome,
    email,
    telefone,
    subtotal: r['{{SUBTOTAL}}'],
    totalFinal: r['{{TOTAL_FINAL}}'],
    requests,
  },
}];
